import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"vex-cli Reference","description":"","frontmatter":{},"headers":[],"relativePath":"references/vex-cli-reference.md","filePath":"references/vex-cli-reference.md"}`),a={name:`references/vex-cli-reference.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="vex-cli-reference" tabindex="-1">vex-cli Reference <a class="header-anchor" href="#vex-cli-reference" aria-label="Permalink to “vex-cli Reference”">​</a></h1><p>This document describes <code>vex-cli</code> architecture, command pipeline, and extension points.</p><hr><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to “Purpose”">​</a></h2><p><code>vex-cli</code> is the primary developer-facing command-line entry for:</p><ul><li>compile (<code>vex compile</code>)</li><li>run (<code>vex run</code>)</li><li>test (<code>vex test</code>)</li><li>semantic analysis and verified cleanup (<code>vex lint</code>)</li><li>toolchain integration with diagnostics, optimizer remarks, and package/native resolution</li></ul><hr><h2 id="command-surface" tabindex="-1">Command Surface <a class="header-anchor" href="#command-surface" aria-label="Permalink to “Command Surface”">​</a></h2><p>Main command modules are under:</p><ul><li><code>tools/vex-cli/src/commands/compile.rs</code></li><li><code>tools/vex-cli/src/commands/run.rs</code></li><li><code>tools/vex-cli/src/commands/test.rs</code></li><li><code>tools/vex-cli/src/commands/lint.rs</code></li><li><code>tools/vex-cli/src/commands/pipeline.rs</code></li></ul><h3 id="vex-compile" tabindex="-1"><code>vex compile</code> <a class="header-anchor" href="#vex-compile" aria-label="Permalink to “vex compile”">​</a></h3><p>Responsibilities:</p><ol><li>Resolve dependencies via <code>vex-pm</code></li><li>Build compiler pipeline via <code>CompilerDriver</code></li><li>Generate object file from LLVM module</li><li>Link executable with: <ul><li>the target-selected embedded native support pack, when required</li><li>target system libraries activated by reachable VexArch providers</li><li>native package linker args (<code>vex_pm::get_native_linker_args_for_source(...)</code>)</li></ul></li><li>Emit optional artifacts (<code>.ll</code>, CFG, coverage)</li></ol><h3 id="vex-run" tabindex="-1"><code>vex run</code> <a class="header-anchor" href="#vex-run" aria-label="Permalink to “vex run”">​</a></h3><p>Responsibilities:</p><ol><li>Resolve deps + compile module</li><li>Link a temporary executable from the fused module, embedded native support, and manifest-owned native dependencies</li><li>Execute and report timings</li></ol><h3 id="comptime-staging-modes" tabindex="-1">Comptime staging modes <a class="header-anchor" href="#comptime-staging-modes" aria-label="Permalink to “Comptime staging modes”">​</a></h3><p><code>vex compile</code>, <code>vex run</code>, and <code>vex ir</code> accept:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--comptime-staging</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disabled</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">analyze</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">apply-known</span></span></code></pre></div><p>The default is <code>disabled</code>. <code>analyze</code> measures opportunistic typed staging while preserving the original HIR and diagnostics. <code>apply-known</code> is the explicit experimental native canary; it transactionally commits only canonical, materialization-ready known islands. Disabling the mode restores the original immutable HIR path. Automatic/default application is not part of V2.</p><p><code>vex lint</code> and <code>vex test</code> retain the observation-only <code>--analyze-comptime</code> option. In test mode it also reaches generated benchmark compilation. Neither command can apply replacements, and LSP&#39;s <code>analyzeComptime</code> setting is likewise observation-only.</p><p>Compile and run additionally accept <code>--comptime-telemetry FILE</code>. It requires a non-disabled <code>--comptime-staging</code> mode and writes the versioned schema-v4 JSON report. Schema v4 separates policy discovery, persistent-cache lookup, record decode, semantic validation, installation and publication from frontend, fusion, LLVM, object and native-link phases. Missing phases are <code>null</code>, and telemetry cannot implicitly enable staging or affect semantic query identity.</p><h3 id="vex-test" tabindex="-1"><code>vex test</code> <a class="header-anchor" href="#vex-test" aria-label="Permalink to “vex test”">​</a></h3><p>Responsibilities:</p><ol><li>Discover <code>*.test.vx</code> / <code>_test.vx</code></li><li>Generate test runner main when needed</li><li>Execute each test function with pass/fail markers</li><li>Handle compile errors and summarize results</li></ol><h3 id="vex-lint" tabindex="-1"><code>vex lint</code> <a class="header-anchor" href="#vex-lint" aria-label="Permalink to “vex lint”">​</a></h3><p>Responsibilities:</p><ol><li>Resolve a <code>.vx</code>/<code>.vxc</code> file, package directory, or nearest <code>vex.json</code></li><li>Run correctness analysis and the shared <code>vex-lint</code> semantic registry without LLVM</li><li>Apply manifest and CLI rule/group levels with CLI precedence</li><li>Emit deterministic text, canonical JSON, or SARIF 2.1.0 diagnostics, including suppression metadata</li><li>Plan revision-bound edits, reject conflicts, and verify semantics for up to four passes</li><li>Atomically write only a fully verified workspace, or print it with <code>--diff</code></li></ol><p>Core options are <code>--fix</code>, <code>--diff</code>, <code>--format text|json|sarif</code>, <code>--deny-warnings</code>, <code>--allow</code>, <code>--warn</code>, <code>--deny</code>, <code>--only</code>, <code>--target</code>, <code>--explain-boxing</code> and <code>--explain-arena</code>. <code>--analyze-comptime</code> adds an observation-only staging summary on stderr. <code>--timings</code> adds opt-in per-rule telemetry to JSON/SARIF; normal runs have no clock-read overhead. The former <code>check</code>, <code>analyze</code> and <code>fix</code> compatibility commands have been removed.</p><p><code>--write-baseline PATH</code> atomically records the current lint set for staged CI; <code>--baseline PATH</code> loads it. Matching findings remain in every output format but do not fail lint warning/deny gates. Correctness errors are never baselined. <code>lint.baseline</code> in <code>vex.json</code> provides a package-relative default.</p><p>Directory inventory is package-scoped: nested manifests and transient test/benchmark runners are not merged into the target. Ordinary lint uses the diagnostics-oriented HIR path and skips codegen module flattening. Full semantic fingerprints are reserved for verified <code>--fix</code>/<code>--diff</code> runs.</p><p>Canonical forms:</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --fix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">vex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --diff</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [TARGET]</span></span></code></pre></div><p><code>--fix</code> writes only after the in-memory result reaches a verified fixed point. <code>--diff</code> runs the same planner and verifier but prints the patch. Syntax-only migrations can operate beside an unrelated pre-existing correctness error; semantic fixes require their proving phase and cannot introduce or alter a correctness failure.</p><p>Rule configuration is read from the nearest <code>vex.json</code>. CLI rule/group levels override manifest levels. Local <code>vex-lint: allow-file</code> and <code>allow-next</code> directives use stable symbolic IDs and are included in JSON metadata.</p><p>The current registry also covers resolved <code>Result</code>/<code>Future</code> misuse, target-aware numeric ranges, allocation effects, and exported API audits. Performance, API, and pedantic rules are opt-in through the <code>performance</code>, <code>library</code>, <code>pedantic</code>, and <code>strict</code> profiles. Semantic body rules share one lazy, revision-bound fact graph with exact call identities and transitive effect summaries. See <a href="/docs/guide/tooling/lint">Linting and Verified Fixes</a> for the complete rule table, configuration, exit codes, suppression syntax, and stability boundary.</p><hr><h2 id="compiler-integration" tabindex="-1">Compiler Integration <a class="header-anchor" href="#compiler-integration" aria-label="Permalink to “Compiler Integration”">​</a></h2><p><code>vex-cli</code> delegates language pipeline to <code>CompilerDriver</code>:</p><ul><li>parsing</li><li>lowering</li><li>type/borrow checks</li><li>codegen</li></ul><p>This keeps command handlers thin while preserving shared compilation behavior.</p><hr><h2 id="linking-model" tabindex="-1">Linking Model <a class="header-anchor" href="#linking-model" aria-label="Permalink to “Linking Model”">​</a></h2><p>VexArch source semantics are rehydrated from the embedded VRI and lowered into the same backend module as user and prelude code. They are not linked from a runtime bitcode module, object, static archive, or dynamic library.</p><p>At native link stage, <code>vex-cli</code> merges:</p><ol><li>a requested-target native support object only when that port requires one;</li><li>system libraries activated by reachable <code>SYSTEM</code>/<code>LIBC</code> providers;</li><li>native args from package manifests (<code>vex-pm</code>).</li></ol><p>The support object contains irreducible assembly only and carries no VexArch semantics. Ordinary cross-boundary optimization happens before object emission inside the fused module.</p><hr><h2 id="execution-model" tabindex="-1">Execution Model <a class="header-anchor" href="#execution-model" aria-label="Permalink to “Execution Model”">​</a></h2><p><code>vex run</code> compiles to a temporary executable and runs it as a subprocess. Native dependencies are resolved via the system linker and dynamic loader at runtime.</p><p><code>vex compile</code> produces a standalone binary from the fused user/prelude/VexArch module plus the explicit target/native link plan. Release packages do not ship a separate Vex runtime library or <code>vex_runtime.bc</code>.</p><hr><h2 id="diagnostics-and-ux" tabindex="-1">Diagnostics and UX <a class="header-anchor" href="#diagnostics-and-ux" aria-label="Permalink to “Diagnostics and UX”">​</a></h2><p><code>vex-cli</code> supports:</p><ul><li>JSON/non-JSON output modes</li><li>optimization remarks</li><li>sanitizer flags</li><li>coverage emission</li><li>lock-file aware dependency workflows</li></ul><hr><h2 id="key-extension-points" tabindex="-1">Key Extension Points <a class="header-anchor" href="#key-extension-points" aria-label="Permalink to “Key Extension Points”">​</a></h2><ul><li>Add new command: <code>tools/vex-cli/src/commands/</code></li><li>Extend CLI flags: command handler signatures + argument parser wiring</li><li>Add new link behavior: compile/run link stage argument builders</li><li>Add test behavior: <code>tools/vex-cli/src/commands/test.rs</code></li></ul><hr><h2 id="operational-notes" tabindex="-1">Operational Notes <a class="header-anchor" href="#operational-notes" aria-label="Permalink to “Operational Notes”">​</a></h2><ul><li>Native linking behavior is package-manifest driven (<code>vex.json/native</code>)</li><li><code>tools/vex-cli/build.rs</code> is intentionally no-op for package native logic (to avoid package-specific hardcoding)</li></ul><hr><h2 id="related-references" tabindex="-1">Related References <a class="header-anchor" href="#related-references" aria-label="Permalink to “Related References”">​</a></h2><ul><li><a href="/docs/guide/tooling/lint">Linting and Verified Fixes</a></li><li><a href="./vex-pm-reference">vex-pm Reference</a></li><li><a href="./vex-pm-native-ffi">vex-pm Native FFI Pipeline</a></li></ul>`,64)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};